INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1, 1, '🐻🌳', '在一片茂密的森林里，住着一只可爱的小熊。它的毛是棕色的，眼睛像两颗亮晶晶的黑葡萄。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1, 2, '🐻🍯', '小熊最喜欢吃蜂蜜了！每天早上，它都会去森林里找蜜蜂朋友，用自己采来的野花换取香甜的蜂蜜。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1, 3, '🐰🌸', '一天，小熊遇到了一只迷路的小兔子。"小熊哥哥，我找不到回家的路了..."小兔子着急得快要哭出来了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1, 4, '🐻🗺️', '"别担心，小兔子！我带你回家！"小熊牵起小兔子的手，穿过森林，跨过小溪，终于找到了小兔子的家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1, 5, '🐰❤️', '小兔子的妈妈感激地说："谢谢你，小熊！你真是一个善良的好孩子！"从那以后，小熊和小兔子成了最好的朋友。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1, 6, '🌟💕', '小熊明白了，帮助别人是一件很快乐的事情。从那以后，森林里的小动物们都喜欢和善良的小熊做朋友。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2, 1, '🌲🎵', '森林里要举办一场盛大的音乐会！小动物们都在忙着准备自己的节目。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2, 2, '🐦🎤', '小鸟正在练习唱歌，它的歌声清脆悦耳，像银铃一样好听。"啦啦啦，森林多美好！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2, 3, '🐰🥁', '小兔子拿来了一面大鼓，咚咚咚地敲着节奏。它说："我来为大家伴奏！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2, 4, '🦊🎻', '小狐狸带来了一把小提琴，它拉出的曲子优美动听，让大家陶醉其中。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2, 5, '🐻🎺', '小熊吹起了小号，虽然它吹得有点跑调，但大家都为它鼓掌加油！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2, 6, '🎉🎶', '音乐会上，每个小动物都展示了自己的才艺。大家唱着、跳着，森林里充满了欢声笑语！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3, 1, '🐰🏠', '小兔子要搬新家啦！它收拾好行李，告别了老邻居们，踏上了寻找新家的旅程。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3, 2, '🐰🌲', '小兔子来到一棵大树下，"这里真好！"它挖了一个洞，铺上软软的草，这就是它的新家了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3, 3, '🦊👋', '邻居小狐狸来敲门："你好，我是小狐狸，欢迎来到森林！"小兔子开心地说："谢谢你！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3, 4, '🐿️🌰', '小松鼠送来了松果，小鸟送来了野花，大家都来欢迎新邻居。小兔子觉得好温暖！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3, 5, '🐰💖', '晚上，小兔子躺在软软的床上，看着窗外的月亮。"新家真好，有这么多好朋友！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3, 6, '🌈✨', '从那以后，小兔子在森林里快乐地生活着，每天都有好朋友来串门，它觉得幸福极了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4, 1, '🌊🐟', '小海豚邀请小乌龟一起去海洋探险！"海底有很多神奇的东西，我们一起去看看吧！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4, 2, '🐠🌊', '他们游过五彩斑斓的珊瑚礁，看到了小丑鱼在海葵里钻来钻去，真有趣！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4, 3, '🐙🐚', '一只章鱼从洞穴里探出头来，它有八只触手，还能变色呢！"欢迎来到我的家！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4, 4, '🐋💙', '他们遇到了巨大的蓝鲸，蓝鲸伯伯说："我是世界上最大的动物，但我只吃小小的磷虾。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4, 5, '🦈🌊', '小鲨鱼游过来，它看起来很凶，但其实很友善。"我来带你们去看海底的宝藏！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4, 6, '💎🌊', '海底有闪闪发光的珍珠和美丽的贝壳，小海豚和小乌龟觉得海底世界真是太神奇了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5, 1, '🐿️🍂', '秋天来了，森林里的树叶变得金黄金黄的。小松鼠知道，该准备过冬的粮食了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5, 2, '🐿️🌰', '小松鼠在树林里跳来跳去，收集松果和坚果。"一颗、两颗、三颗..."它把食物藏到树洞里。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5, 3, '🐿️🍁', '树叶纷纷落下，小松鼠用叶子把自己裹得暖暖的。"这样就不怕冷了！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5, 4, '🐻🧡', '小熊看见了，也来帮忙。它爬上树，把高处的松果摇下来给小松鼠捡。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5, 5, '❄️🐿️', '冬天来了，小松鼠躲在温暖的树洞里，吃着美味的松果，心里感谢帮助过它的朋友们。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5, 6, '🌟💖', '小松鼠明白了，勤劳和友谊让它度过了一个温暖的冬天。明年秋天，它也要帮助更多朋友！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6, 1, '🐧❄️', '小企鹅住在寒冷的南极。妈妈说："小企鹅，你该学游泳了！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6, 2, '🐧😰', '小企鹅看着冰冷的海水，有点害怕。"水好冷啊，我不敢下去..."');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6, 3, '🐧💪', '妈妈鼓励它："别怕，我们企鹅是天生的游泳健将！你一定可以的！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6, 4, '🐧💦', '小企鹅鼓起勇气，扑通一声跳进水里。"咦？我在水里会浮起来呢！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6, 5, '🐧🐟', '小企鹅学着妈妈的样子划水，很快就能游得很快了。它还抓到了一条小鱼！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6, 6, '🎉🐧', '"太棒了！我学会游泳了！"小企鹅开心极了。原来勇敢尝试，就能做到！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7, 1, '🌳🩺', '啄木鸟是森林里的医生。它每天在树上"笃笃笃"地敲着，给大树治病。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7, 2, '🐛😱', '大树生病了，叶子都枯黄了。啄木鸟检查后发现树干里有好多害虫在捣乱！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7, 3, '🪶💪', '啄木鸟用尖尖的嘴巴啄开树皮，把害虫一只只揪出来。"看你们还敢不敢欺负大树！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7, 4, '🌳😊', '治好了病，大树又长出了绿油油的叶子。"谢谢你，啄木鸟医生！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7, 5, '🪶❤️', '啄木鸟说："不用谢，帮助大家是我应该做的！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7, 6, '🌲✨', '森林里的大树都健康成长，多亏了勤劳的啄木鸟医生。它是最受欢迎的森林小卫士！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8, 1, '🐱🎣', '小猫和妈妈一起去河边钓鱼。小猫拿着鱼竿，坐在河边等待鱼儿上钩。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8, 2, '🦋🌸', '一只美丽的蝴蝶飞过来，小猫放下鱼竿去追蝴蝶。蝴蝶飞走了，小猫什么也没抓到。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8, 3, '🐸🍀', '一只青蛙跳过来，小猫又去追青蛙。青蛙跳进水里，小猫还是什么也没抓到。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8, 4, '🐱🐟', '妈妈已经钓了好几条鱼了，小猫的桶里却空空的。"为什么我一条鱼也钓不到呢？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8, 5, '🐱💪', '妈妈说："钓鱼要专心，不能三心二意。"小猫点点头，认真地看着鱼漂。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8, 6, '🐟🎉', '终于，鱼漂动了！小猫用力一拉，钓到了一条大鱼！"我做到了！专心做事才能成功！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9, 1, '🐛🍃', '一片叶子上，住着一条小小的毛毛虫。它每天不停地吃叶子，慢慢长大。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9, 2, '🐛💤', '有一天，毛毛虫吐出丝，把自己包裹起来，变成了一个茧。它在里面安静地睡着。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9, 3, '茧✨', '过了好几天，茧动了一下，接着裂开了一条缝。有什么东西要出来了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9, 4, '🦋🌟', '一只美丽的蝴蝶从茧里飞了出来！它的翅膀五彩斑斓，像一朵会飞的花。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9, 5, '🦋🌸', '蝴蝶飞到花丛中，吸食花蜜。"我原来是毛毛虫，现在变成了美丽的蝴蝶，真神奇！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9, 6, '🌈🦋', '蝴蝶在花丛中翩翩起舞，它明白了成长的过程虽然漫长，但结果如此美好！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10, 1, '🐘❓', '小象有一根长长的鼻子，它觉得自己的鼻子太长了，不好看。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10, 2, '🐘😊', '妈妈说："你的鼻子可是宝贝呢！它可以做很多事。"小象不太相信。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10, 3, '🐘💦', '天气很热，小象用鼻子吸水，然后喷在身上给自己洗澡。"哇，好凉快！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10, 4, '🐘🍃', '小象用鼻子卷起地上的树叶，送到嘴里吃。"原来鼻子像手一样好用！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10, 5, '🐘❤️', '朋友摔倒了，小象用鼻子把它扶起来。"谢谢你的长鼻子！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10, 6, '🐘✨', '小象终于明白了，每个人都有自己独特的地方。它的长鼻子是它最好的礼物！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11, 1, '🦊🌲', '在一片美丽的森林里，住着一只可爱的小狐狸。它有着火红火红的毛，非常漂亮。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11, 2, '🦊😔', '小狐狸很聪明，但总觉得森林里的动物们都躲着它。"为什么大家都不愿意和我玩呢？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11, 3, '🐰👋', '有一天，小狐狸鼓起勇气，走向正在采蘑菇的小白兔。"你好，我们能做朋友吗？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11, 4, '🦊🎀', '小狐狸从身后拿出一朵漂亮的野花，送给小白兔。小白兔接过了花，露出了一点点笑容。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11, 5, '🐰🤝', '"谢谢你，小狐狸！你真友好！"小白兔说，"我们一起玩吧！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11, 6, '🌟💕', '小狐狸开心极了，它明白了交朋友的秘诀：真诚和善良。从那以后，它成了森林里最受欢迎的小动物！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12, 1, '🦛👄', '河马有一张大大的嘴巴，是动物王国里嘴巴最大的。它常常担心自己的嘴巴太大了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12, 2, '🦛😊', '一天，小猴子掉进了河里，它不会游泳，在大声呼救！"救命啊！救命啊！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12, 3, '🦛💪', '河马听到了，立刻跳进水里，用大嘴巴轻轻托起小猴子，把它送到岸边。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12, 4, '🐒❤️', '小猴子得救了！它感激地说："谢谢你，河马！你的大嘴巴真棒！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12, 5, '🦛✨', '河马这才明白，自己的大嘴巴不是缺点，而是可以帮助别人的优点！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12, 6, '🌈💖', '从那以后，河马不再为大嘴巴烦恼了。它用大嘴巴帮助了很多朋友，成了河里的大英雄！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13, 1, '🐒🍑', '小猴子最喜欢吃桃子了！有一天，它发现了一棵结满桃子的树。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13, 2, '🐒🤔', '小猴子摘了一个桃子，咬了一口，就把桃子扔了。"不好吃，我要找更甜的！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13, 3, '🐒🏃', '小猴子又摘了一个，吃一口又扔了。就这样，它扔了很多桃子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13, 4, '🐒😓', '最后，树上的桃子都被它摘光了，它却一个也没吃完。小猴子肚子饿得咕咕叫。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13, 5, '👴🌳', '老猴子爷爷看见了，说："孩子，做事要专注，不能三心二意。你浪费了这么多桃子！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13, 6, '🐒💖', '小猴子明白了道理，从此它吃东西时都会认真品尝，不再浪费食物了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14, 1, '🐢🐰', '森林里要举办跑步比赛，骄傲的兔子说："我跑得最快，冠军肯定是我的！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14, 2, '🐢💪', '小乌龟慢慢地说："我也要参加比赛！"兔子哈哈大笑："你这么慢，怎么可能赢？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14, 3, '🐰😴', '比赛开始了，兔子跑得飞快，很快就把乌龟甩在后面。它想："乌龟那么慢，我睡一觉再跑也来得及。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14, 4, '🐢💦', '小乌龟一步一步慢慢爬，它不休息，不停歇，一直往前爬。"我不能放弃！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14, 5, '🐢🎉', '当兔子醒来时，发现乌龟已经到达终点了！大家都为小乌龟欢呼！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14, 6, '🌟🐢', '小乌龟赢了！它用行动告诉大家：坚持就是胜利，骄傲会让人失败。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15, 1, '🐝🌸', '春天来了，花园里开满了五颜六色的花朵。小蜜蜂要开始工作了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15, 2, '🐝✈️', '小蜜蜂飞到一朵花上，用长长的嘴巴吸取花蜜。"嗡嗡嗡，花儿真香！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15, 3, '🐝🍯', '小蜜蜂把花蜜存在肚子里的蜜囊中，飞回蜂巢，把花蜜变成甜甜的蜂蜜。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15, 4, '🐝🏠', '蜂巢里，成千上万只蜜蜂一起工作。有的采蜜，有的酿蜜，有的照顾小蜜蜂。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15, 5, '🐝❤️', '小蜜蜂虽然很累，但它很开心。"我们的蜂蜜可以给人们带来甜蜜，我们的工作很有意义！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15, 6, '🍯✨', '勤劳的小蜜蜂教会我们：努力工作，团结合作，才能创造美好的生活！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76, 1, '👶🔬', '欢迎来到人体奥秘的世界！我们的身体就像一个超级精密的机器，每时每刻都在工作！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76, 2, '❤️💓', '这是我们的心脏，它只有拳头那么大，却非常有力！心脏每天要跳动约10万次，把血液输送到全身。咚咚咚，你听到心跳的声音了吗？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76, 3, '🧠💭', '大脑是我们身体的"总指挥"！它只有1.4公斤重，却掌管着我们的思考、记忆、学习。你的大脑里有大约1000亿个神经细胞呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76, 4, '👀🌈', '我们的眼睛就像一台神奇的照相机！它能看到几百万种颜色，还能在黑暗和光明中自动调节。眨眼的时候，眼睛就在给自己洗澡哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76, 5, '👂🎵', '耳朵不仅能听到声音，还帮助我们保持平衡。耳朵里有一万多个小小的毛细胞，它们把声音变成信号传给大脑。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76, 6, '🦷🍎', '牙齿是我们身体里最坚硬的部分！小朋友有20颗乳牙，长大后会有32颗恒牙。记得每天刷牙两次，保护我们的牙齿卫士哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76, 7, '🦴🏃', '我们的身体有206块骨头！它们支撑着我们的身体，保护着重要的器官。最小的骨头在耳朵里，最大的骨头是大腿骨。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76, 8, '💪✨', '肌肉让我们能够运动！身体里有600多块肌肉。微笑一下，你就用了17块肌肉哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76, 9, '🫁🌬️', '肺是我们呼吸的"气球"！我们每天大约呼吸2万次，吸入氧气，呼出二氧化碳。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76, 10, '🧪🔬', '我们的身体真是太神奇了！希望你保持好奇心，好好爱护自己的身体，它会陪伴你一辈子哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77, 1, '🚀🌍', '小朋友，你有没有仰望过夜空？那些闪烁的小星星，其实都是遥远的太阳！让我们一起去探索神奇的太空吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77, 2, '🌙⭐', '看！那是我们的月亮。月亮上没有空气，也没有水，所以没有生命。但是，月亮上有许多有趣的山和坑，叫做环形山。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77, 3, '🔴🪐', '这是火星，因为它红红的，所以叫"火星"。火星上最高的山比地球上的珠穆朗玛峰还要高三倍呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77, 4, '🪐💫', '哇！那是土星！看它漂亮的光环，其实是无数的小冰块和小石头组成的。土星可以装下700多个地球呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77, 5, '☀️🌟', '那是我们的太阳！太阳是一颗恒星，它一直在发光发热。太阳光到达地球需要8分钟呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77, 6, '🌌✨', '宇宙中有无数的星星和行星。也许有一天，你也会成为一名宇航员，去探索这些神秘的星球！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78, 1, '🦕🌴', '很久很久以前，在6500万年前的地球上，生活着一群神奇的动物——恐龙！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78, 2, '🦖🌿', '霸王龙是恐龙之王！它有尖尖的牙齿，强壮的后腿，是最凶猛的肉食恐龙。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78, 3, '🦕🌳', '腕龙是一种超级大的恐龙，它的脖子像长颈鹿一样长，可以吃到很高很高的树叶。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78, 4, '🥚👶', '恐龙是从蛋里孵出来的！恐龙妈妈会在沙土里挖一个坑，把蛋生在里面。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78, 5, '☄️😱', '可惜，大约6500万年前，一颗巨大的陨石撞击了地球，恐龙们从此消失了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78, 6, '🦴🔬', '科学家们通过研究恐龙化石，了解恐龙的生活。也许有一天，你也能成为一名古生物学家！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79, 1, '🌸🌱', '春天来了！小草从土里探出头，树木长出了嫩绿的新芽，花儿都开放了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79, 2, '☀️🏊', '夏天到了！太阳火辣辣的，我们可以吃冰激凌、游泳、捉知了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79, 3, '🍂🍁', '秋天来了！树叶变成了金黄色，纷纷落下。果园里的水果都成熟了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79, 4, '❄️⛄', '冬天到了！天空飘起了雪花，我们堆雪人、打雪仗，真好玩！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79, 5, '🔄❤️', '四季就这样循环变化着。每个季节都有自己的美丽，我们要用心感受大自然的变化！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79, 6, '🌈✨', '大自然真神奇！让我们珍惜每一个季节，享受大自然的馈赠吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80, 1, '🐛🐜', '欢迎来到昆虫王国！昆虫是地球上数量最多的动物，它们有着神奇的本领。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80, 2, '🦋🌸', '蝴蝶是昆虫王国里最美丽的居民。它们有五彩斑斓的翅膀，在花丛中翩翩起舞。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80, 3, '🐝🍯', '蜜蜂是最勤劳的昆虫。它们采花蜜、酿蜂蜜，为我们带来甜蜜的食物。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80, 4, '🐜💪', '蚂蚁虽然很小，但力气很大。它们团结合作，可以搬运比自己重很多倍的东西。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80, 5, '🦗🎵', '蟋蟀是昆虫音乐家，夏天的夜晚，它们在草丛里唱着美妙的歌。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80, 6, '🌟🔍', '昆虫王国里还有很多秘密等着你去发现。下次看到小昆虫，不妨仔细观察一下！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81, 1, '🌱🌍', '植物是地球上最重要的生物之一！它们为我们提供氧气、食物和美丽的风景。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81, 2, '🌻☀️', '植物通过光合作用，用阳光、水和空气制造自己的食物。它们是地球的"氧气工厂"！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81, 3, '🌸🦋', '花儿开放是为了吸引昆虫来传播花粉。花谢之后，就会结出果实和种子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81, 4, '🌳🏠', '大树是很多动物的家。小鸟在树上筑巢，松鼠在树洞里储存粮食。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81, 5, '🍃🍂', '秋天，树叶会变黄变红，然后落下。这是大树在为冬天保存能量。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81, 6, '🌱✨', '植物的生命力真神奇！一粒小小的种子，可以长成参天大树。让我们爱护植物，保护绿色家园！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82, 1, '☀️🌌', '太阳系是一个大家庭，太阳是家长，围绕着它旋转的有八大行星。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82, 2, '🌍🏠', '地球是我们的家，它是唯一有生命存在的行星。有海洋、陆地、空气和水。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82, 3, '🔴🪐', '火星是红色的行星，科学家们正在研究它，也许未来人类可以在火星上生活！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82, 4, '🪐💍', '土星有漂亮的光环，那是由冰块和岩石组成的。土星是太阳系第二大行星。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82, 5, '🌙💫', '月亮是地球的好朋友，它围着地球转，给我们带来夜晚的光明。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82, 6, '🚀🌟', '太阳系真神奇！小朋友，好好学习，将来也许你能驾驶飞船去探索太空呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21, 1, '👧❤️', '小雨今天不太开心。她坐在门口，低着头不说话。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21, 2, '👩❤️', '妈妈走过来，什么也没说，只是轻轻地抱住了小雨。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21, 3, '👧😊', '小雨在妈妈的怀里，感到好温暖。所有的不开心都飞走了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21, 4, '💕✨', '"妈妈，为什么抱抱这么神奇？"小雨问。妈妈笑着说："因为抱抱里藏着爱！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21, 5, '👨‍👩‍👧💖', '爸爸回来了，小雨跑过去给了爸爸一个大大的拥抱。"我爱你们！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21, 6, '🌟🤗', '小雨明白了，爱是可以传递的。一个拥抱，就能让人感到幸福。她要把拥抱送给更多的人！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16, 1, '👧👦', '小明是小红最好的朋友。他们一起上学，一起玩耍，形影不离。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16, 2, '👧📚', '有一天，小红生病了，不能去上学。她很想小明，也很担心落下功课。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16, 3, '👦🎒', '放学后，小明来到小红家，把今天的功课讲给她听，还带来了她最爱吃的糖果。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16, 4, '👧❤️', '小红感动地说："谢谢你，小明！"小明笑着说："好朋友就是要互相帮助！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16, 5, '🌈🤝', '小红病好了，又和小明一起快乐地玩耍。他们的友谊更加深厚了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16, 6, '💖✨', '真正的朋友会在你需要的时候陪伴你、帮助你。珍惜友谊，友谊会让我们更快乐！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25, 1, '👧🏠', '小芳是一个善良的小女孩。她总是关心身边的人，帮助他们解决困难。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25, 2, '👴🚶', '一天，小芳看到邻居老爷爷走路很慢，还拿着重重的菜篮子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25, 3, '👧💪', '小芳跑过去说："爷爷，我来帮您提菜篮子！"老爷爷开心地笑了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25, 4, '👦😢', '在公园里，小芳看到一个小弟弟在哭，原来是气球飞走了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25, 5, '👧🎈', '小芳用自己的零花钱给小弟弟买了一个新气球。小弟弟开心地笑了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25, 6, '❤️✨', '关心别人，帮助别人，自己也会感到快乐。小芳成了大家最喜欢的小朋友！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33, 1, '👦🌙', '小强很怕黑。每天晚上睡觉，他都要开着小夜灯，还要妈妈陪在身边。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33, 2, '👦😰', '一天晚上，家里突然停电了。四周黑漆漆的，小强害怕极了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33, 3, '💡✨', '妈妈点燃了蜡烛，温暖的烛光照亮了房间。"看，黑暗中也有光！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33, 4, '👦💪', '妈妈说："黑暗其实不可怕，可怕的是你心里的恐惧。勇敢地面对它！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33, 5, '👦🌟', '小强慢慢平静下来，他发现黑暗中也有美好的东西——窗外的星星在眨眼呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33, 6, '🎉✨', '从那以后，小强不再怕黑了。他明白了，勇敢的心能战胜一切恐惧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17, 1, '👧💕', '今天是母亲节，小丽想给妈妈一个特别的惊喜。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17, 2, '👧🎨', '小丽画了一幅画，画的是妈妈和她手牵手在公园散步。画上写着"妈妈我爱你"。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17, 3, '👧🍳', '小丽还学着做了早餐，虽然煎蛋有点糊，但她很用心。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17, 4, '👩😊', '妈妈醒来，看到了画和早餐，感动得流下了眼泪。"谢谢你，宝贝！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17, 5, '👧🤗', '小丽紧紧抱住妈妈："妈妈，您辛苦了！我永远爱您！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17, 6, '💖✨', '妈妈的爱是最伟大的爱。我们要好好爱妈妈，让她每天都开心！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18, 1, '👦👨', '小明的爸爸是一名消防员。小明觉得爸爸是世界上最棒的爸爸！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18, 2, '👨🚒', '每当有火灾，爸爸总是冲在最前面，保护大家的安全。小明很崇拜爸爸。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18, 3, '👦🏠', '爸爸工作很忙，但只要有时间，就会陪小明踢足球、讲故事。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18, 4, '👨❤️', '有一天，爸爸在救火时受了伤。小明心疼地说："爸爸，您辛苦了！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18, 5, '👨👦', '爸爸笑着说："保护大家是我的责任。你也要做一个勇敢、负责任的人！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18, 6, '💪✨', '小明的爸爸真棒！每个爸爸都是孩子心中的英雄。让我们对爸爸说：谢谢您，我爱您！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27, 1, '👧🍪', '小红有一盒美味的饼干，她想自己一个人慢慢地吃。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27, 2, '👧🤔', '这时，几个小朋友走过来，他们看着小红的饼干，都很想吃。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27, 3, '👧😊', '小红想了想，把饼干分给了大家。"来，我们一起吃！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27, 4, '👧👦🍪', '小朋友们开心地吃着饼干，有说有笑。小红发现，和大家一起吃比自己一个人吃更快乐！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27, 5, '❤️✨', '小红明白了，分享不是失去，而是获得更多的快乐。分享让友谊更美好！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27, 6, '🤝🌈', '从那以后，小红有好东西都会和朋友分享。她成了大家最喜欢的小伙伴！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34, 1, '👦💪', '小刚是个胆小的男孩，他怕黑、怕高、怕虫子...什么都怕。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34, 2, '👦😰', '一天，小刚看到一只小猫被困在树上，它害怕地喵喵叫。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34, 3, '👦🤔', '小刚很想救小猫，但他怕高。"我该怎么办？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34, 4, '👦💪', '小刚深吸一口气，鼓起勇气爬上了树。他抱着小猫，小心地爬下来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34, 5, '🐱❤️', '小猫得救了！小刚的爸爸妈妈都为他鼓掌："你真勇敢！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34, 6, '🏆✨', '小刚明白了，勇敢不是不害怕，而是虽然害怕但还是会去做对的事情。他是个勇敢的孩子！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35, 1, '👧🌸', '小美总觉得自己很普通，没有什么特别的。她羡慕别人比自己漂亮、聪明、能干。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35, 2, '👩❤️', '妈妈知道后，拿出了一面镜子，让小美仔细看看自己。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35, 3, '👧👀', '"看看你的眼睛，多明亮！看看你的笑容，多温暖！看看你的心，多善良！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35, 4, '👧😊', '小美笑了。她发现，自己也有很多优点。她善良、爱帮助人、会画画...这些都是她的特别之处。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35, 5, '✨❤️', '妈妈说："每个人都是独一无二的，你就是你，很特别的你！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35, 6, '🌟🌈', '小美明白了，不需要和别人比较。做最好的自己，就是最特别的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36, 1, '👦🏺', '小华在玩耍时，不小心打碎了妈妈最喜欢的花瓶。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36, 2, '👦😰', '小华很害怕，心想：如果妈妈知道了，会不会生气呢？要不要说是猫打破的？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36, 3, '👦🤔', '小华想了很久，最后决定告诉妈妈真相。他不想做一个撒谎的孩子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36, 4, '👩😊', '妈妈听了，不但没有生气，还摸了摸小华的头。"花瓶碎了没关系，但你诚实地承认错误，妈妈很高兴！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36, 5, '👦❤️', '小华松了一口气。他明白了，诚实比什么都重要。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36, 6, '💎✨', '诚实是最珍贵的品质。做一个诚实的孩子，会赢得大家的信任和尊重！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37, 1, '👧🎂', '今天是小兰的生日，她7岁了！她觉得自己长大了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37, 2, '👧👔', '小兰发现，以前的衣服变短了，鞋子变小了。"我长大了！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37, 3, '👧📚', '小兰可以自己读书、自己系鞋带、自己收拾书包了。"我能做很多事了！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37, 4, '👧🏠', '小兰还学会了帮妈妈做家务，扫地、擦桌子、洗碗。"我可以帮妈妈分担了！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37, 5, '👩❤️', '妈妈说："长大不仅是长高，更是学会独立、学会关心别人。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37, 6, '🌟✨', '小兰开心地说："我长大了，我要做一个懂事的好孩子！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64, 1, '👧😢', '从前，有一个善良美丽的女孩，名叫灰姑娘。她被继母和姐姐们欺负，每天要做很多家务。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64, 2, '✨👗', '王子要举办舞会，仙女教母用魔法把灰姑娘变成了美丽的公主，还给她变出了水晶鞋。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64, 3, '💃🏰', '灰姑娘在舞会上和王子跳舞，他们是那么般配。但魔法只能维持到午夜。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64, 4, '👠🏃', '午夜的钟声响了，灰姑娘匆忙离开，不小心跑掉了一只水晶鞋。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64, 5, '👸❤️', '王子拿着水晶鞋寻找它的主人。最后，只有灰姑娘穿得下这只鞋！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64, 6, '👑✨', '灰姑娘和王子结婚了，从此过上了幸福的生活。善良的人终会有好报！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65, 1, '👸🍎', '美丽的白雪公主被恶毒的皇后赶出城堡，她在森林里遇到了七个善良的小矮人。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65, 2, '👵🍎', '恶毒的皇后扮成老婆婆，给白雪公主一个有毒的苹果。白雪公主吃了一口，就昏睡过去了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65, 3, '王子❤️', '邻国的王子路过，看到美丽的白雪公主，爱上了她。他轻轻地吻了她。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65, 4, '👸✨', '神奇的事情发生了！白雪公主醒了过来，毒苹果的魔力消失了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65, 5, '👑🎉', '王子带着白雪公主回到城堡，他们举行了盛大的婚礼，幸福地生活在一起。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65, 6, '💖✨', '善良和美丽的心灵，终究会战胜邪恶。白雪公主的故事告诉我们：要做善良的人！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56, 1, '👧🏠', '小红帽要去看望生病的奶奶，妈妈让她走大路，不要和陌生人说话。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56, 2, '🐺🌲', '路上，小红帽遇到了一只大灰狼。狡猾的狼骗小红帽去采花，自己跑去奶奶家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56, 3, '🐺👵', '大灰狼把奶奶吞进肚子，又扮成奶奶的样子躺在床上，等着小红帽。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56, 4, '👧😰', '小红帽来到奶奶家，发现"奶奶"的样子很奇怪。"奶奶，你的耳朵怎么这么大？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56, 5, '🐺😱', '"是为了听得更清楚！"狼跳起来要吃小红帽。这时，猎人叔叔冲进来救了她们！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56, 6, '👧✨', '小红帽和奶奶得救了！她明白了：不能轻信陌生人，要学会保护自己。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55, 1, '🐷🏠', '三只小猪长大了，要自己盖房子住。猪大哥盖了草房，猪二哥盖了木房，猪小弟盖了砖房。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55, 2, '🐺💨', '大灰狼来了！它吹了一口气，就把草房吹倒了。猪大哥逃到了猪二哥的木房。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55, 3, '🐺💨', '大灰狼又吹了一口气，木房也被吹倒了！两只小猪逃到了猪小弟的砖房。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55, 4, '🐺😤', '大灰狼吹呀吹，砖房纹丝不动。它想从烟囱钻进去，结果掉进热水锅里烫跑了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55, 5, '🐷🎉', '三只小猪高兴地欢呼起来！猪小弟的砖房救了他们。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55, 6, '💪✨', '三只小猪明白了：做事要认真踏实，不能偷懒。辛苦盖的房子才能保护好自己！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66, 1, '🥚🐥', '鸭妈妈孵出了一群小鸭子，其中有一只又大又丑。大家都叫他"丑小鸭"，没有人喜欢他。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66, 2, '🐥😢', '丑小鸭很难过，他离开了家，独自流浪。冬天来了，他又冷又饿。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66, 3, '🐥🌱', '春天来了，丑小鸭看到水中的倒影——他变成了一只美丽的天鹅！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66, 4, '🦢✨', '原来，丑小鸭不是鸭子，而是一只小天鹅！他终于找到了自己的家人。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66, 5, '🦢💖', '丑小鸭变成了最美的天鹅，他在湖中优雅地游泳，感到无比幸福。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66, 6, '🌈✨', '每个人都有自己的闪光点，不要因为别人的眼光而否定自己。相信自己，你也是最美的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67, 1, '🐢🐰', '骄傲的兔子嘲笑乌龟跑得慢。乌龟说："我们来比赛跑步吧！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67, 2, '🐰💨', '比赛开始了！兔子跑得飞快，一下子就把乌龟甩在后面很远。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67, 3, '🐰😴', '兔子想："乌龟那么慢，我睡一觉再跑也来得及。"它在树下睡着了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67, 4, '🐢💦', '乌龟一步一步地爬，它不休息，不停歇，一直坚持向前。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67, 5, '🐢🎉', '当兔子醒来时，乌龟已经到达终点了！大家都为乌龟欢呼！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67, 6, '🏆✨', '乌龟赢了！这个故事告诉我们：骄傲使人落后，坚持就是胜利！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68, 1, '👦🖌️', '马良是一个爱画画的穷孩子，但他买不起笔。一天晚上，一位老爷爷送给他一支神笔。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68, 2, '🖌️🐄', '马良发现，神笔画的东西都会变成真的！他画了一头牛，牛就活了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68, 3, '👦❤️', '马良用神笔帮助穷苦的百姓。他画粮食、画衣服、画房子，大家都感激他。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68, 4, '👑😰', '贪心的皇帝知道了，把马良抓起来，逼他画金山银山。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68, 5, '🖌️🌊', '马良画了一片大海，皇帝坐船去金山。马良又画了大风浪，把贪心的皇帝冲走了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68, 6, '🌈✨', '马良回到了百姓身边，继续用神笔帮助大家。善良的力量是最强大的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69, 1, '👦🏠', '孔融是一个聪明懂事的孩子。有一天，爸爸买了一筐梨回家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69, 2, '🍐🍐', '哥哥们都在挑大梨，只有孔融挑了一个最小的。爸爸问："你为什么拿最小的？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69, 3, '👦😊', '孔融说："我年纪小，应该吃小的。哥哥们年纪大，应该吃大的。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69, 4, '👨❤️', '爸爸听了很感动："你真是个懂事的好孩子！懂得谦让是美德！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69, 5, '🤝✨', '哥哥们也被孔融感动了，大家一起开心地吃着梨。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69, 6, '💖✨', '孔融让梨的故事告诉我们：要懂得谦让，尊敬兄长，关爱他人。这是中华民族的传统美德！');